"""The tp4/sched-1 window pack (scripts/ci/references/fusion-jobs/SCH, generated by make_sched_jobs.py).

ORDER.txt lists exactly the folder's templates, each once, on the one image, with a total that matches its header; every NEEDS line names earlier jobs; every smoke job carries the two Swift
checkpoint keys and every prefix-gate job none (that step does not forward them); every pair differs by the profile alone; every template parses through the job reader with rc 0; the
pack is what the generator makes; nothing in it names a host, an address or a registry; the measurement it names but the tree does not hold (agent_turns, built on another branch) is the one
forward reference, said so in ORDER.txt."""

import json
from pathlib import Path
import re
import subprocess
import sys
import unittest

HERE = Path(__file__).resolve().parent
if str(HERE) not in sys.path:
    sys.path.insert(0, str(HERE))

import c2_serving_job as job  # noqa: E402
import make_sched_jobs as pack  # noqa: E402
import make_sched_profiles as twins  # noqa: E402

PACK = pack.FOLDER
READER = HERE / 'c2_serving_job.py'
PROFILES = HERE / 'qwen_c2_profiles.json'
CATALOG = json.loads((HERE / 'qwen_c2_checkpoints.json').read_text(encoding='utf-8'))
SWIFT = CATALOG['checkpoints'][0]
ARM = pack.ARM
TIER = ('tier-concurrent-timed', pack.SHIP)

# job -> (mode, serves Swift, profile, smoke tests, prefix plan)
EXPECTED = {
    'B0-build-window': ('stop', False, '', '', None),
    'X0-status-rescan-reset': ('stop', False, '', '', None),
    'A1-sch-audited-attach': ('stop', True, ARM['all-audit'], pack.AUDIT_TESTS, None),
    'S1-sch-tier-audited': ('stop', False, '', '', 'tier-concurrent'),
    'C1-control-a': ('soft', True, pack.SHIP, pack.TIMED_TESTS, None),
    'L1-all-a': ('soft', True, ARM['all'], pack.TIMED_TESTS, None),
    'C2-control-b': ('soft', True, pack.SHIP, pack.TIMED_TESTS, None),
    'L2-all-b': ('soft', True, ARM['all'], pack.TIMED_TESTS, None),
    'LE1-lean-a': ('soft', True, ARM['lean'], pack.TIMED_TESTS, None),
    'PA1-pace-a': ('soft', True, ARM['pace'], pack.TIMED_TESTS, None),
    'FD0-few-control': ('soft', True, pack.SHIP, pack.FEW_TESTS, None),
    'FD1-few-adaptive': ('soft', True, ARM['adaptive'], pack.FEW_TESTS, None),
    'T0-tier-control-a': ('soft', False, '', '', 'tier-concurrent-timed'),
    'T1-tier-spill-a': ('soft', False, '', '', 'tier-concurrent-timed'),
    'T2-tier-control-b': ('soft', False, '', '', 'tier-concurrent-timed'),
    'T3-tier-spill-b': ('soft', False, '', '', 'tier-concurrent-timed'),
    'Z-reset': ('soft', False, '', '', None),
}
# the profile each prefix-gate job serves
PREFIX_PROFILE = {'S1-sch-tier-audited': ARM['all-audit'], 'T0-tier-control-a': pack.SHIP, 'T1-tier-spill-a': ARM['spill'], 'T2-tier-control-b': pack.SHIP, 'T3-tier-spill-b': ARM['spill']}


def order_lines():
    return [line.split() for line in (PACK / 'ORDER.txt').read_text(encoding='utf-8').splitlines() if line.strip() and not line.startswith('#')]


def directives(prefix):
    return [line[len(prefix):].split() for line in (PACK / 'ORDER.txt').read_text(encoding='utf-8').splitlines() if line.startswith(prefix)]


def values(name):
    return job.parse_env((PACK / (name + '.env')).read_text(encoding='utf-8'))


def run_reader(path):
    result = subprocess.run([sys.executable, '-B', '-s', str(READER), str(path), str(PROFILES)], stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=str(HERE.parent.parent))
    return result.returncode, (result.stdout + result.stderr).decode('utf-8', 'replace')


class OrderTests(unittest.TestCase):
    def test_order_lists_exactly_the_folders_templates_once_on_one_image(self):
        rows = order_lines()
        self.assertEqual([row[0] for row in rows], list(EXPECTED), 'in value order')
        self.assertEqual(sorted(path.stem for path in PACK.glob('*.env')), sorted(EXPECTED))
        self.assertEqual({row[2] for row in rows}, {pack.IMAGE})
        self.assertEqual(pack.IMAGE, 'tp4-sched-1')
        for row in rows:
            self.assertEqual(row[1], EXPECTED[row[0]][0], row[0])
            self.assertEqual(values(row[0])['C2_IMAGE_TAG'], pack.IMAGE)

    def test_the_header_total_matches_the_minutes(self):
        text = (PACK / 'ORDER.txt').read_text(encoding='utf-8')
        minutes = sum(int(row[3]) for row in order_lines())
        self.assertIn('%d minutes (%d h %d min) in all' % (minutes, minutes // 60, minutes % 60), text)
        for row in order_lines():
            self.assertIn('%s %s' % (row[0].split('-')[0], row[3]), text)

    def test_needs_lines_name_earlier_jobs_only(self):
        names = [row[0].split('-')[0] for row in order_lines()]
        for left_right in directives('# NEEDS '):
            arrow = left_right.index('<-')
            left, right = left_right[:arrow], left_right[arrow + 1:]
            for job_name in left + right:
                self.assertIn(job_name, names)
            for later in left:
                for earlier in right:
                    self.assertLess(names.index(earlier), names.index(later), left_right)
        needed = {token for line in directives('# NEEDS ') for token in line[:line.index('<-')]}
        self.assertEqual(needed, set(names) - {'B0', 'Z'}, 'every serving job waits for something; the build and the reset wait for nothing')

    def test_the_arc_range_covers_every_audited_and_timed_boot_and_nothing_else(self):
        names = [row[0].split('-')[0] for row in order_lines()]
        ((first, last),) = directives('# ARC-ZERO ')
        self.assertEqual((first, last), ('A1', 'T3'))
        for token in names:
            inside = names.index(first) <= names.index(token) <= names.index(last)
            self.assertEqual(inside, token not in ('B0', 'X0', 'Z'), token)

    def test_the_order_says_what_is_unqualified_what_decides_and_the_forward_reference(self):
        text = (PACK / 'ORDER.txt').read_text(encoding='utf-8')
        for phrase in ('Never cancel a running card job', 'UNQUALIFIED', 'owner traffic waiver', 'agent_turns', 'is NOT in this branch', "the owner's, never the window's", 'sliced restore'):
            self.assertIn(phrase, text)
        for name in EXPECTED:
            self.assertIn('no tag is pushed from the branch by its author', (PACK / (name + '.env')).read_text(encoding='utf-8'))

    def test_the_one_measurement_the_tree_may_not_hold_is_agent_turns(self):
        """Every smoke test the pack names is in c2_serving_smoke.py of this tree but the measurement of another branch (a forward reference ORDER.txt says; once that branch is merged this
        holds trivially and the P0 line of ORDER.txt can go)."""
        smoke = (HERE / 'c2_serving_smoke.py').read_text(encoding='utf-8')
        missing = {test for _mode, _swift, _profile, tests, _plan in EXPECTED.values() for test in filter(None, tests.split(',')) if "def %s(" % test not in smoke and "'%s'" % test not in smoke}
        self.assertLessEqual(missing, {pack.MEASURE})
        if missing:
            self.assertIn('is NOT in this branch', (PACK / 'ORDER.txt').read_text(encoding='utf-8'))


class TemplateTests(unittest.TestCase):
    def test_every_template_parses_with_rc_0(self):
        for name in EXPECTED:
            with self.subTest(name=name):
                code, text = run_reader(PACK / (name + '.env'))
                self.assertEqual(code, 0, text)

    def test_serving_jobs_carry_the_checkpoint_keys_and_the_expected_profile_tests_and_plan(self):
        for name, (_mode, serves_swift, profile, tests, plan) in EXPECTED.items():
            with self.subTest(name=name):
                found = values(name)
                if serves_swift:
                    self.assertEqual((found['C2_MODEL_REPO'], found['C2_MODEL_REVISION']), (SWIFT['repo'], SWIFT['revision']))
                    self.assertEqual((pack.REPO, pack.REVISION), (SWIFT['repo'], SWIFT['revision']))
                else:
                    self.assertNotIn('C2_MODEL_REPO', found)
                    self.assertNotIn('C2_MODEL_REVISION', found)
                self.assertEqual(found.get('C2_PROFILE', ''), profile)
                self.assertEqual(found.get('C2_SMOKE_TESTS', ''), tests)
                self.assertEqual(found.get('C2_PREFIX_PLAN'), plan)
                if plan:
                    self.assertEqual(found['C2_PREFIX_PROFILE'], PREFIX_PROFILE[name])
                    self.assertEqual(found['C2_PREFIX_BASELINE'], 'none')

    def test_every_profile_a_job_names_is_a_twin_or_the_approved_one(self):
        profiles = json.loads(PROFILES.read_text(encoding='utf-8'))['profiles']
        for name in EXPECTED:
            found = values(name)
            for key in ('C2_PROFILE', 'C2_PREFIX_PROFILE'):
                if found.get(key):
                    self.assertIn(found[key], profiles, name)
                    self.assertIn(found[key], set(twins.NAMES) | {pack.SHIP}, name)

    def test_no_job_uses_a_step_that_does_not_forward_the_checkpoint_when_it_carries_it(self):
        for name in EXPECTED:
            found = values(name)
            actions = set(found['C2_ACTIONS'].split())
            if found.get('C2_MODEL_REPO'):
                self.assertFalse(actions - set(job.MODEL_ACTIONS), name)
            self.assertFalse(actions & {'gate', 'replay', 'push', 'agentstop', 'agentstart', 'unserve', 'platform'}, name)

    def test_the_build_bakes_the_approved_ship_profile_with_the_oneq_graft_and_never_a_twin(self):
        found = values('B0-build-window')
        self.assertEqual((found['C2_BAKE_DEFAULT_PROFILE'], found['C2_BAKE_GRAFT']), (pack.SHIP, 'K64j-OQ'))
        entry = json.loads(PROFILES.read_text(encoding='utf-8'))['profiles'][pack.SHIP]
        self.assertFalse(job.bake_waiver_pending(entry), 'the ship-4 waiver is APPROVED: the build is not refused')
        for name in EXPECTED:
            if name != 'B0-build-window':
                self.assertNotIn('C2_BAKE_DEFAULT_PROFILE', values(name), name)

    def test_the_pairs_differ_by_the_profile_alone_and_the_control_is_the_approved_profile(self):
        keys = ('C2_SMOKE_TESTS', 'C2_BOX_MINUTES', 'C2_IMAGE_TAG', 'C2_MODEL_REPO', 'C2_MODEL_REVISION', 'C2_CARDS', 'C2_ACTIONS', 'C2_TELEMETRY')
        for control, arm in (('C1-control-a', 'L1-all-a'), ('C2-control-b', 'L2-all-b'), ('C1-control-a', 'LE1-lean-a'), ('C1-control-a', 'PA1-pace-a'), ('FD0-few-control', 'FD1-few-adaptive')):
            self.assertEqual([values(control).get(key) for key in keys], [values(arm).get(key) for key in keys], (control, arm))
            self.assertEqual(values(control)['C2_PROFILE'], pack.SHIP)
        for control, arm in (('T0-tier-control-a', 'T1-tier-spill-a'), ('T2-tier-control-b', 'T3-tier-spill-b')):
            keys = ('C2_ACTIONS', 'C2_IMAGE_TAG', 'C2_PREFIX_PLAN', 'C2_PREFIX_BASELINE', 'C2_BOX_MINUTES', 'C2_CARDS')
            self.assertEqual([values(control).get(key) for key in keys], [values(arm).get(key) for key in keys], (control, arm))
            self.assertEqual((values(control)['C2_PREFIX_PROFILE'], values(arm)['C2_PREFIX_PROFILE']), (pack.SHIP, ARM['spill']))

    def test_each_smoke_job_names_the_steady_test_and_a_box_inside_the_step(self):
        for name, (_mode, _swift, _profile, tests, _plan) in EXPECTED.items():
            found = values(name)
            if 'smoke' not in found['C2_ACTIONS'].split():
                continue
            with self.subTest(name=name):
                self.assertIn('concurrent8_steady', tests.split(','))
                self.assertTrue(0 < int(found['C2_BOX_MINUTES']) <= 210)
                self.assertEqual(found['C2_CARDS'], 'quad')
                self.assertEqual(found['C2_TELEMETRY'], '1')

    def test_the_audited_attach_runs_the_all_audit_twin_with_every_lever(self):
        found = values('A1-sch-audited-attach')
        self.assertEqual(found['C2_PROFILE'], ARM['all-audit'])
        self.assertGreater(int(found['C2_BOX_MINUTES']), int(order_lines()[2][3]), 'the box is longer than the estimate')
        text = re.sub(r'\s*\n#\s*', ' ', (PACK / 'A1-sch-audited-attach.env').read_text(encoding='utf-8'))
        for phrase in ('the lean admission', 'complete spills', 'returning-turn pacing', 'few-decoder policy', 'NO "audit mismatch"'):
            self.assertIn(phrase, text)

    def test_the_templates_name_the_readers_and_the_lines_the_arms_log(self):
        text = re.sub(r'\s*\n#\s*', ' ', (PACK / 'L1-all-a.env').read_text(encoding='utf-8'))
        for phrase in ('sched_report.py', 'admission lean split', 'lever N sched: owed_cap_ms=1500', 'lever N adaptive: decoders<=2', 'host tier spill complete on', 'agent_turns', 'EQUAL turn for turn'):
            self.assertIn(phrase, text)
        text = re.sub(r'\s*\n#\s*', ' ', (PACK / 'T1-tier-spill-a.env').read_text(encoding='utf-8'))
        for phrase in ('tier_concurrent_compare.py', 'IDENTICAL', '254k restore', 'control-to-control FLOOR'):
            self.assertIn(phrase, text)
        text = re.sub(r'\s*\n#\s*', ' ', (PACK / 'FD1-few-adaptive.env').read_text(encoding='utf-8'))
        self.assertIn('prefill_ladder_report.py', text)

    def test_the_tools_the_templates_name_exist(self):
        for tool in ('sched_report.py', 'tier_concurrent_compare.py', 'prefill_ladder_report.py', 'qwen_c2_checkpoint.py'):
            self.assertTrue((HERE / tool).is_file(), tool)


class GeneratedTests(unittest.TestCase):
    def test_the_checked_in_pack_is_what_the_generator_makes(self):
        self.assertEqual(pack.main(['--check']), 0)

    def test_nothing_in_the_pack_names_a_host_an_address_or_a_registry(self):
        for path in PACK.glob('*'):
            text = path.read_text(encoding='utf-8')
            with self.subTest(path=path.name):
                self.assertEqual([needle for needle in ('/home/', 'zot.', 'ghcr', 'docker.io', '.local', '.internal', 'localhost') if needle in text], [])
                self.assertIsNone(re.search(r'\b(?:\d{1,3}\.){3}\d{1,3}\b', text), 'an IP address')
                self.assertIsNone(re.search(r'blackhole-[0-9A-F]{16}', text), 'a card id')
                self.assertIsNone(re.search(r'\bsha256:[0-9a-f]{12,}', text), 'an image digest')


if __name__ == '__main__':
    unittest.main()
